preConditionHook:
// Entry & Exit Confessions #6 (Percent Ranker), verbatim: ADX strictly
// between adxLow and adxHigh (both strict, as the book writes them) AND the
// close beyond the interpolated percentile value of the last xbars closes.
// MultiWalk's WFSafe_ADX, copied statement for statement from
// AdxBelowThreshold via EecThreeAmigos (the bit-exact reference;
// EL_ADX_Probe.txt, scripts/adx_replica.py). Seeds at the study's first
// calculated bar with fresh Length-term DM/TR sums, followed by EMA-form
// updates with SF = 1/Length; oADX warms up as Cum(oDMI)/CurrentBar through
// bar Length. el_gt in the DM classification is decisive (near-ties from
// grid-price differences). No re-seed on a length change. The hook-scope
// temporaries of the reference (sfAdx, dmiPlus, dmiMinus, divisor, dmi) are
// DECLARED locals here so they take the placement prefix and cannot collide
// with AdxBelowThreshold or EecThreeAmigos in the same strategy.
adxSf = 1 / adxLength;
if (ctx.CurrentBar() == 1) {
    double sumPlusDM = 0.0;
    double sumMinusDM = 0.0;
    double sumTR = 0.0;
    for (int i = 0; i < (int)adxLength; ++i) {
        double upMove = high[i] - high[i + 1];
        double dnMove = low[i + 1] - low[i];
        double plusDM = 0.0;
        double minusDM = 0.0;
        if (el_gt(upMove, dnMove) && el_gt(upMove, 0.0)) plusDM = upMove;
        else if (el_gt(dnMove, upMove) && el_gt(dnMove, 0.0)) minusDM = dnMove;
        sumPlusDM += plusDM;
        sumMinusDM += minusDM;
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        sumTR += hi - lo;
    }
    avgPlusDM = sumPlusDM / adxLength;
    avgMinusDM = sumMinusDM / adxLength;
    volty = sumTR / adxLength;
} else {
    double upMove = high[0] - high[1];
    double dnMove = low[1] - low[0];
    double plusDM = 0.0;
    double minusDM = 0.0;
    if (el_gt(upMove, dnMove) && el_gt(upMove, 0.0)) plusDM = upMove;
    else if (el_gt(dnMove, upMove) && el_gt(dnMove, 0.0)) minusDM = dnMove;
    avgPlusDM = avgPlusDM + adxSf * (plusDM - avgPlusDM);
    avgMinusDM = avgMinusDM + adxSf * (minusDM - avgMinusDM);
    double hi = high[0] > close[1] ? high[0] : close[1];
    double lo = low[0] < close[1] ? low[0] : close[1];
    volty = volty + adxSf * ((hi - lo) - volty);
}
dmiPlus = 0.0;
dmiMinus = 0.0;
if (el_gt(volty, 0.0)) {
    dmiPlus = 100 * avgPlusDM / volty;
    dmiMinus = 100 * avgMinusDM / volty;
}
dmiDivisor = dmiPlus + dmiMinus;
dmiVal = 0.0;
if (el_gt(dmiDivisor, 0.0)) dmiVal = 100 * std::fabs(dmiPlus - dmiMinus) / dmiDivisor;
// Cum() is a series function: it accumulates every bar regardless of which
// oADX branch runs.
cumDmi = cumDmi + dmiVal;
if (ctx.CurrentBar() <= adxLength) {
    adxVal = cumDmi / ctx.CurrentBar();
} else {
    adxVal = adxVal + adxSf * (dmiVal - adxVal);
}
// EL's Percentile(pct, series, N) per the VERIFIED register row
// (EL_Percentile_Probe.txt / el_percentile_output.txt): copy the window of
// bars 0..N-1 -- current bar INCLUDED -- sort it and linearly interpolate
// at rank = pct*(N-1) between the two adjacent sorted values (Excel
// PERCENTILE.INC; duplicates are interpolated across). pct is a 0..1
// FRACTION; out of range returns EL's -1 sentinel (measured at pct = 25).
// The window is the close SERIES, which has real pre-first-bar history, so
// no zero-fill mirror is needed. Both values are computed every bar, as the
// book's Value1/Value2 assignments are -- one sort serves both, since
// Percentile is a pure function of the same window. Interpolation
// temporaries live in block scope.
eprSorted.assign((std::size_t)(int)xbars, 0.0);
for (int i = 0; i < (int)xbars; ++i) eprSorted[(std::size_t)i] = close[i];
// Insertion sort, ascending, in plain loops -- the only non-EL construct is
// the buffer itself (the AtrRising std::vector precedent). The comparisons
// inside the sort are between tick-grid closes, where the EL tolerance
// cannot bind (differences are 0 or >= 1 tick).
for (int i = 1; i < (int)xbars; ++i) {
    double key = eprSorted[(std::size_t)i];
    int j = i - 1;
    while (j >= 0 && eprSorted[(std::size_t)j] > key) {
        eprSorted[(std::size_t)(j + 1)] = eprSorted[(std::size_t)j];
        j = j - 1;
    }
    eprSorted[(std::size_t)(j + 1)] = key;
}
eprHigh = 0.0;
if (percentileHigh < 0.0 || percentileHigh > 1.0) {
    eprHigh = -1.0;
} else {
    double rank = percentileHigh * ((int)xbars - 1);
    int lo = (int)rank;
    double frac = rank - lo;
    eprHigh = eprSorted[(std::size_t)lo];
    if (frac > 0.0) eprHigh = eprHigh + frac * (eprSorted[(std::size_t)(lo + 1)] - eprSorted[(std::size_t)lo]);
}
eprLow = 0.0;
if (percentileLow < 0.0 || percentileLow > 1.0) {
    eprLow = -1.0;
} else {
    double rank = percentileLow * ((int)xbars - 1);
    int lo = (int)rank;
    double frac = rank - lo;
    eprLow = eprSorted[(std::size_t)lo];
    if (frac > 0.0) eprLow = eprLow + frac * (eprSorted[(std::size_t)(lo + 1)] - eprSorted[(std::size_t)lo]);
}
